  q(EMER,'A patient has a seizure in the dental chair. What is the first step?','Clear the area and protect the patient',['Hold the patient firmly still','Place fingers in the mouth to block','Give water to drink'],'D','Time the seizure and call 911 if it lasts longer than 5 minutes.',ROB),
  q(EMER,'A patient is choking and cannot speak or cough. What should the dental team do?','Give abdominal thrusts',['Give water to drink','Wait for the cough','Lay the patient back'],'A','Abdominal thrusts are continued until the object is expelled or the patient is unresponsive.',ROB),
  q(EMER,'Which drug is given for a severe allergic reaction in the dental office?','Epinephrine',['Nitroglycerin','Albuterol','Glucose gel'],'B','Epinephrine is given by injection into the thigh muscle; call 911 right away.',ROB)
